from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    out_h, out_w = h // 3, w // 3
    output = [[0 for _ in range(out_w)] for _ in range(out_h)]

    for out_row in range(out_h):
        for out_col in range(out_w):
            in_row = 3 * out_row
            in_col = 3 * out_col

            non_zero_five_values = []
            for i in range(in_row, in_row + 3):
                for j in range(in_col, in_col + 3):
                    val = grid[i][j]
                    if val not in (0, 5):
                        non_zero_five_values.append(val)

            if non_zero_five_values:
                counts = Counter(non_zero_five_values)
                most_frequent = counts.most_common(1)[0][0]
                output[out_row][out_col] = most_frequent

    return output


